//! Status lines on stderr: stdout is for results, and for the protocol in MCP mode.
//! Generated by anything-anything.
#![allow(dead_code)]

use std::fmt::Display;
use std::io::IsTerminal;
use std::sync::OnceLock;

fn color() -> bool {
    static COLOR: OnceLock<bool> = OnceLock::new();
    *COLOR.get_or_init(|| std::env::var_os("NO_COLOR").is_none() && std::io::stderr().is_terminal())
}

fn paint(code: &str, s: impl Display) -> String {
    if color() { format!("\x1b[{code}m{s}\x1b[0m") } else { s.to_string() }
}

pub fn brand(s: impl Display) -> String {
    paint("38;2;220;38;38", s)
}

pub fn bold(s: impl Display) -> String {
    paint("1", s)
}

pub fn dim(s: impl Display) -> String {
    paint("2", s)
}

pub fn step(s: impl Display) {
    eprintln!("{} {s}", brand("▸"));
}

pub fn ok(s: impl Display) {
    eprintln!("{} {s}", paint("32", "✓"));
}

pub fn warn(s: impl Display) {
    eprintln!("{} {s}", paint("33", "!"));
}

pub fn error(s: impl Display) {
    eprintln!("{} {s}", paint("31", "✗"));
}
